alter table public.clinics add column if not exists facility_model text not null default 'single_site'
  check (facility_model in ('single_site','multi_branch_clinic','multi_clinic_network','hospital','multi_hospital_network','polyclinic','diagnostic_centre'));
alter table public.clinics add column if not exists specialties text[] not null default array['general_medicine']::text[];
alter table public.clinics add column if not exists enabled_modules text[] not null default array['patients','appointments','consultation','prescriptions','billing']::text[];
alter table public.clinics add column if not exists clinic_profile jsonb not null default '{}'::jsonb;
alter table public.clinics drop constraint if exists clinics_clinic_type_check;
alter table public.clinics add constraint clinics_clinic_type_check check (clinic_type in ('general_opd','general_medicine','dental','orthodontics','oral_surgery','periodontics','prosthodontics','eye','ophthalmology','optometry','skin','dermatology','cosmetology','pediatrics','neonatology','gynecology','obstetrics','fertility','orthopedic','sports_medicine','physiotherapy','neurology','cardiology','diabetology','endocrinology','gastroenterology','pulmonology','nephrology','urology','ENT','ent','psychiatry','psychology','oncology','rheumatology','geriatrics','pain_management','ayurveda','homeopathy','unani','siddha','naturopathy','diagnostic_lab','radiology_centre','pathology_lab','imaging_centre','dialysis_centre','vaccination_centre','urgent_care','polyclinic','nursing_home','maternity_home','day_care_centre','rehabilitation_centre','fertility_centre','eye_hospital','dental_hospital','hospital','multi_specialty_hospital','super_specialty_hospital','other'));
create or replace function public.platform_admin_configure_clinic_profile(p_clinic_id uuid,p_facility_model text,p_specialties text[],p_enabled_modules text[])
returns jsonb language plpgsql security definer set search_path to '' as $function$
declare v_specialties text[] := coalesce(p_specialties,array['general_medicine']::text[]); v_modules text[] := coalesce(p_enabled_modules,array['patients','appointments','consultation','prescriptions','billing']::text[]);
begin
 if not private.is_platform_admin() then raise exception 'Platform super-admin permission required'; end if;
 if p_facility_model not in ('single_site','multi_branch_clinic','multi_clinic_network','hospital','multi_hospital_network','polyclinic','diagnostic_centre') then raise exception 'Unsupported facility model'; end if;
 if cardinality(v_specialties)>20 or exists(select 1 from unnest(v_specialties) s where s not in ('general_medicine','dentistry','orthodontics','oral_surgery','periodontics','prosthodontics','ophthalmology','optometry','dermatology','cosmetology','pediatrics','neonatology','gynecology','obstetrics','fertility','orthopedics','sports_medicine','physiotherapy','neurology','cardiology','diabetology','endocrinology','gastroenterology','pulmonology','nephrology','urology','ent','psychiatry','psychology','oncology','rheumatology','geriatrics','pain_management','ayurveda','homeopathy','unani','siddha','naturopathy','pathology','radiology','dialysis','vaccination','emergency_medicine','surgery','anesthesia','icu','nephrology_dialysis','rehabilitation','nutrition','family_medicine','other')) then raise exception 'Invalid specialty selection'; end if;
 if cardinality(v_modules)>40 or exists(select 1 from unnest(v_modules) m where m not in ('patients','appointments','consultation','prescriptions','billing','pharmacy','laboratory','multi_branch','ipd','radiology','operation_theatre','emergency','blood_bank','cssd','diet','ambulance','procurement','asset_management','insurance','hr_payroll','telemedicine','referrals','clinical_quality','patient_portal','offline_sync','nursing','inventory','documents','reports')) then raise exception 'Invalid module selection'; end if;
 update public.clinics set facility_model=p_facility_model,specialties=v_specialties,enabled_modules=v_modules,updated_at=now() where id=p_clinic_id;
 if not found then raise exception 'Clinic not found'; end if;
 insert into public.platform_audit_logs(actor_user_id,action,entity_type,entity_id,details) values(auth.uid(),'configure_clinic_profile','clinic',p_clinic_id::text,jsonb_build_object('facility_model',p_facility_model,'specialties',v_specialties,'enabled_modules',v_modules));
 return jsonb_build_object('clinic_id',p_clinic_id,'facility_model',p_facility_model,'specialties',v_specialties,'enabled_modules',v_modules);
end; $function$;
revoke all on function public.platform_admin_configure_clinic_profile(uuid,text,text[],text[]) from public,anon;
grant execute on function public.platform_admin_configure_clinic_profile(uuid,text,text[],text[]) to authenticated;
